INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('76f69795-93e1-49b9-976a-681235984e52', 'Late Fees', '7', '2', 'PAGOS', E'- If the tenant doesn''t pay rent and maintenance fees, including VAT, as agreed, they must pay a late fee.\n- The late fee is 2% of the current monthly rent.\n- This interest is calculated from the date the payment is late until it is fully paid.\n- Interest is calculated monthly, even if the delay is just one day.\n- Paying late fees doesn''t extend the payment deadline or change any payment obligations in the contract.', 'Para el caso de que la Arrendataria no cubra la renta y el mantenimiento con el respectivo Impuesto al Valor Agregado en la forma estipulada, ésta se obliga a pagar al Arrendador, sí así éste se lo requiere, un interés moratorio equivalente al 2% (dos por ciento) del monto de la renta mensual que se encuentre en vigor, que habrá de ser calculado, a partir de la fecha en que incurra en mora y hasta la fecha en que efectivamente sea pagado el importe de tales conceptos; en el entendido que el cómputo de este interés, se hará por períodos mensuales, no obstante que la morosidad corresponda a un solo día. El pago de intereses moratorios no se interpretará como una extensión del plazo o prórroga para el pago de las cantidades que la Arrendataria se obliga a pagar al Arrendador conforme a este contrato, ni como una dispensa, remisión, compensación o novación de cualquier obligación de la Arrendataria de pagar todas las cantidades que se deriven del presente contrato en la fecha o fechas establecidas en el mismo.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('76f69795-93e1-49b9-976a-681235984e52', 'Incremento de Renta', '7', '5', 'AJUSTE DE LA RENTA Y DEL MANTENIMIENTO', E'- La Renta Mensual aumentará en el mes 25 y luego cada 12 meses.\n- El aumento se basa en el Índice Nacional de Precios al Consumidor (INPC) publicado por el INEGI.\n- El porcentaje de aumento de la renta también se aplicará a la Cuota de Mantenimiento.\n- La Cuota de Mantenimiento se incrementará anualmente en el mismo porcentaje que la Renta.', E'Las Partes convienen que la Renta Mensual será incrementada al mes 25 y posteriormente cada 12 (doce) meses, en el entendido de que el periodo que se indica se contará a partir de la apertura del local o el término del periodo de gracia, lo que ocurra primero. Los ajustes al importe de la Renta Mensual se incrementarán de acuerdo con la siguiente mecánica:\n\nSe tomará como base el porcentaje que haya variado el Índice Nacional de Precios al Consumidor (INPC), que publica mensualmente el Instituto Nacional de Estadística y Geografía (INEGI) en los doce meses previos al inicio del contrato de arrendamiento o, en su caso, o al del último ajuste de renta. El porcentaje aplicado al monto de la renta también aplicará al incremento de la Cuota de Mantenimiento\n\nLa cuota de mantenimiento se incrementará anualmente en un porcentaje igual al de la Renta');
